  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The Higgs boson discovery completed a central part of the Standard Model and opened a new era of precision tests. It is an exceptionally consequential experimental achievement.",
        "attribution": "The discovery depended on two large collaborations; recognizing these leaders is a defensible way to credit the experimental conception and execution, though the work was irreducibly collective.",
        "maturity": "The boson has been repeatedly observed and its properties tested since 2012, with substantial agreement with the Standard Model.",
        "uncertainties": [
          "Individual credit within the ATLAS and CMS collaborations is necessarily selective."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP precision mapping made the cosmic microwave background a quantitative foundation for modern cosmology and sharply constrained the universe's composition and history.",
        "attribution": "Bennett and Page represent the mission's experimental leadership, while Spergel's central role in extracting cosmological implications makes the interpretation part of the achievement.",
        "maturity": "The measurements have been extensively checked and were followed by higher-resolution CMB observations that broadly confirmed the resulting cosmological picture.",
        "uncertainties": [
          "The award boundary between WMAP's measurement achievement and the broader development of precision cosmology is not self-evident."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Frans Pretorius",
        "John G. Baker",
        "Manuela Campanelli"
      ],
      "assessment": {
        "nobel_worthiness": "Stable simulations of merging black holes solved a long-standing problem and supplied the waveforms needed to identify and interpret the first gravitational-wave detections.",
        "attribution": "Pretorius established the breakthrough, followed by independent numerical-relativity advances by Baker and Campanelli's groups; credit to all three reflects that sequence, while omitting many contributors.",
        "maturity": "The methods have been validated against observed binary black-hole signals and are now central to gravitational-wave astronomy.",
        "uncertainties": [
          "The Nobel-sized contribution could be framed as the numerical breakthrough, the later observational discovery, or their combination."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope imaging gave a striking direct view of emission around a black hole and tested strong-gravity predictions in a previously inaccessible regime.",
        "attribution": "Falcke helped articulate the imaging opportunity, Zensus contributed major VLBI leadership, and Doeleman led the observing effort; the image depended on a large international collaboration.",
        "maturity": "The M87 image has been followed by further analyses and observations, including imaging of Sagittarius A*, though the method and interpretation remain active areas of refinement.",
        "uncertainties": [
          "The resolution-limited ring is an image of surrounding emission rather than a direct view of the event horizon itself.",
          "Credit among the many contributors to the EHT collaboration is difficult to compress into three names."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Christian Spiering",
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrinos as a new astronomical messenger, extending observation beyond electromagnetic radiation and connecting particle physics with energetic cosmic sources.",
        "attribution": "Halzen was a central scientific architect and leader; Spiering was instrumental in developing and advancing the detector project. The achievement rests on a major international collaboration.",
        "maturity": "The diffuse astrophysical neutrino flux is firmly established, while the identification and characterization of its sources continue to improve.",
        "uncertainties": [
          "The astrophysical sources responsible for much of the observed flux are not yet fully identified."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "David Charbonneau",
        "Sara Seager",
        "William J. Borucki"
      ],
      "assessment": {
        "nobel_worthiness": "Transit measurements transformed exoplanets from isolated discoveries into a population that can be measured, compared, and studied for atmospheric properties. This opened a sustained new branch of observational astrophysics.",
        "attribution": "Charbonneau demonstrated the power of transit observations, Borucki led the Kepler effort that made population statistics possible, and Seager helped establish the theoretical and observational framework for planetary characterization.",
        "maturity": "Transit surveys have yielded large, independently confirmed samples and repeated atmospheric measurements, though the field's methods and targets continue to expand.",
        "uncertainties": [
          "The broad discovery combines several stages and projects, making a single sharply defined prize contribution difficult to isolate."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought timekeeping to a level where relativistic effects and subtle changes in gravitational potential can be measured in the laboratory, while creating a powerful platform for precision tests.",
        "attribution": "Katori and Ye independently developed leading approaches and sustained the experimental advances that established the field.",
        "maturity": "Clock performance has been demonstrated repeatedly across laboratories, and comparisons now test fundamental physics as well as metrology.",
        "uncertainties": [
          "The distinction between a mature discovery and an instrumentation program still undergoing rapid improvement is a matter of timing."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Marta Burgay",
        "Michael Kramer"
      ],
      "assessment": {
        "nobel_worthiness": "The double pulsar provided an unusually rich strong-field laboratory and stringent tests of general relativity, including effects relevant to gravitational-wave emission.",
        "attribution": "Burgay led the discovery observation, while Kramer led the precision timing work that turned the system into a powerful gravity test.",
        "maturity": "Long-term timing measurements have repeatedly confirmed relativistic predictions with high precision.",
        "uncertainties": [
          "The achievement is a superb test of general relativity but has not yet revealed a clear deviation or a new gravitational principle."
        ]
      }
    }
  ]
}
